// Validate & normalize the inbound intake payload.
// Defensive by design: never throws on missing or malformed fields.
const body = $input.first().json?.body || {};

const str = (v, max) => String(v ?? '').trim().slice(0, max);

const lead = {
  first_name: str(body?.first_name, 80),
  last_name:  str(body?.last_name, 80),
  email:      str(body?.email, 254).toLowerCase(),
  company:    str(body?.company, 160),
  phone:      str(body?.phone, 40),
  source:     str(body?.source, 40) || 'web_form',
  message:    str(body?.message, 4000),
};

const errors = [];
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email);
if (!emailOk) errors.push('email is missing or invalid');
if (!lead.first_name) errors.push('first_name is required');
if (lead.message.length < 10) errors.push('message must be at least 10 characters');

// Strip characters commonly used to break out of prompt delimiters.
lead.message = lead.message.replace(/[<>]/g, '');

return [{ json: { valid: errors.length === 0, errors, lead } }];

