// Treat LLM output as untrusted input: parse, validate against the schema,
// and fall back to a safe default that routes the lead to human review.
const lead = $('Validate & Normalize Input').first().json?.lead || {};
const resp = $input.first().json || {};

const TIERS = ['Starter', 'Growth', 'Enterprise', 'Not a fit'];
const fallback = {
  summary: 'Automatic qualification unavailable. Route to manual review.',
  recommended_tier: 'Not a fit',
  qualification_score: 0,
  needs_human_review: true,
  reason: 'llm_output_invalid',
};

let result = fallback;
try {
  const text = resp?.content?.[0]?.text || '';
  const parsed = JSON.parse(text);
  const score = Number(parsed?.qualification_score);
  const valid =
    typeof parsed?.summary === 'string' && parsed.summary.length > 0 &&
    TIERS.includes(parsed?.recommended_tier) &&
    Number.isInteger(score) && score >= 0 && score <= 100;

  if (valid) {
    result = {
      summary: parsed.summary.slice(0, 1000),
      recommended_tier: parsed.recommended_tier,
      qualification_score: score,
      // Low-confidence or high-value leads always get a human look.
      needs_human_review: score < 40 || parsed.recommended_tier === 'Enterprise',
      reason: 'ok',
    };
  }
} catch (e) {
  // keep fallback
}

return [{ json: { lead, qualification: result } }];

